@section('content')<h1>{{ $record ? 'Изменить черновик' : 'Создать черновик' }}</h1><form class="admin-form" method="post" action="{{ $record ? route('admin.calculators.update', $record->id) : route('admin.calculators.store') }}">@csrf @if($record) @method('PUT') @endif<label>Название<input name="name" maxlength="120" required value="{{ old('name', $record?->name) }}"></label><label>Тип<select name="type">@foreach($definitions as $code => $definition)<option value="{{ $code }}" @selected(old('type', $record?->type) === $code)>{{ $definition['name'] }}</option>@endforeach</select></label><label>Подзаголовок<input name="subtitle" maxlength="300" value="{{ old('subtitle', $record?->subtitle) }}"></label><label>Годовая ставка, %<input name="rate" inputmode="decimal" required value="{{ old('rate', $record?->rate) }}"></label><label>Параметры JSON<textarea name="parameters" rows="8" required>{{ old('parameters', $record ? json_encode($record->parameters, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE) : '') }}</textarea></label><details><summary>Состав параметров по типам</summary>@foreach($definitions as $definition)<h3>{{ $definition['name'] }}</h3><pre>{{ json_encode($definition['parameters'], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE) }}</pre>@endforeach</details><p>Черновик останется внутри панели и не появится на сайте.</p><div class="admin-actions"><button class="button primary" type="submit">Сохранить</button><a class="button" href="{{ route('admin.calculators') }}">Отмена</a></div></form>@endsection
